"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[948],{7948:e=>{e.exports=JSON.parse('{"id":5,"name":"Equilibrium","researcher":{"fullName":"John Forbes Nash Jr.","lastName":"Nash","image":"/img/roadmap/nash.svg","bio":"Mathematician and Nobel laureate whose equilibrium concept revealed how stable, self-sustaining patterns emerge from independent agents pursuing their own interests."},"details":{"tagline":"Self-Sustaining Global Infrastructure","description":"When the frameworks, practices, and paradigm of thinking become self-sustaining without the founding team, the mission succeeds. New researchers extend the work in directions the original team never imagined. Multiple institutions maintain the infrastructure. The ideas spread because they\'re instrumentally useful - better coordination mechanisms actually work better. This is the end of the roadmap because the work continues without us. It\'s genuinely valuable, not because we\'re still around to push it."},"publications":[]}')}}]);